#!/usr/bin/env python3

from __future__ import annotations

import calendar
import curses
import datetime as dt
import hashlib
import locale
import os
import re
import shlex
import shutil
import subprocess
import sys
from collections import Counter, defaultdict
from dataclasses import dataclass, field
from pathlib import Path
from typing import Dict, Iterable, List, Optional, Sequence, Tuple


VERSION = "commit-93cc85d16ab60ba8d646458fe0233778317b22a3"
DEFAULT_LOG_NAME_FORMAT = "y%Y/d%Y_%m_%d.md"
DEFAULT_LOG_DIR_NAME = ".caps-log/day"
DEFAULT_CONFIG_NAME = ".caps-log/config.ini"
ROOT_SECTION = "<root section>"

HELP_TEMPLATE = """Captain's Log (caps-log)! A CLI journalig tool.
Version: {version}
Allowed options:
  -h [ --help ]         show this message
  -c [ --config ] arg   override the default config file path
                        ({config_path})
  --log-dir-path arg    path where log files are stored
  --log-name-format arg format in which log entry markdown files are saved
  --sunday-start        have the calendar display sunday as first day of the
                        week
  --first-line-section  override the default behaviour of ignoring sections
                        (lines starting with `#`) in the first line of a log
                        entry file
  --password arg        password for encrypted log repositories or to be used
                        with --encrypt/--decrypt
  --encrypt             apply encryption to all logs in log dir path (needs
                        --password)
  --decrypt             apply decryption to all logs in log dir path (needs
                        --password)
"""


class CapsLogError(Exception):
    pass


@dataclass
class ParsedArgs:
    help: bool = False
    config_path: Optional[str] = None
    log_dir_path: Optional[str] = None
    log_name_format: Optional[str] = None
    sunday_start: bool = False
    first_line_section: bool = False
    password: Optional[str] = None
    encrypt: bool = False
    decrypt: bool = False


@dataclass
class AnnualEvent:
    group: str
    name: str
    month: int
    day: int


@dataclass
class Settings:
    config_path: Path
    log_dir: Path
    log_name_format: str
    sunday_start: bool
    first_line_section: bool
    password: Optional[str]
    encrypt: bool
    decrypt: bool
    recent_events_window: int = 60
    annual_events: List[AnnualEvent] = field(default_factory=list)


@dataclass
class LogEntry:
    date: dt.date
    path: Path
    content: str
    section_names: List[str]
    tags: List[Tuple[str, str]]


@dataclass
class PromptModal:
    kind: str
    title: str
    buffer: str = ""
    hidden: bool = False
    choice: int = 0


def default_config_path() -> Path:
    return Path.home() / DEFAULT_CONFIG_NAME


def default_log_dir() -> Path:
    return Path.home() / DEFAULT_LOG_DIR_NAME


def format_error(message: str) -> str:
    return f"Captain's log encountered an error: \n {message}\n"


def normalize_name(value: str) -> str:
    return " ".join(value.strip().lower().split())


def normalize_tag(value: str) -> str:
    text = value.strip()
    if not text:
        return ""
    for marker in ("(", ":"):
        pos = text.find(marker)
        if pos != -1:
            text = text[:pos]
    return normalize_name(text)


def strip_inline_comment(value: str) -> str:
    if value.startswith("#"):
        return value
    for marker in (" #", " ;"):
        pos = value.find(marker)
        if pos != -1:
            return value[:pos].rstrip()
    return value.rstrip()


def parse_bool(value: str) -> bool:
    return value.strip().lower() in {"1", "true", "yes", "on"}


def expand_path(value: Optional[str]) -> Optional[Path]:
    if value is None:
        return None
    return Path(os.path.expanduser(value))


def parse_args(argv: Sequence[str]) -> ParsedArgs:
    args = ParsedArgs()
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg in ("-h", "--help"):
            args.help = True
            i += 1
            continue
        if arg in ("-c", "--config"):
            i += 1
            if i >= len(argv):
                raise CapsLogError("the required argument for option '--config' is missing")
            args.config_path = argv[i]
            i += 1
            continue
        if arg.startswith("--config="):
            args.config_path = arg.split("=", 1)[1]
            i += 1
            continue
        if arg == "--log-dir-path":
            i += 1
            if i >= len(argv):
                raise CapsLogError("the required argument for option '--log-dir-path' is missing")
            args.log_dir_path = argv[i]
            i += 1
            continue
        if arg.startswith("--log-dir-path="):
            args.log_dir_path = arg.split("=", 1)[1]
            i += 1
            continue
        if arg == "--log-name-format":
            i += 1
            if i >= len(argv):
                raise CapsLogError("the required argument for option '--log-name-format' is missing")
            args.log_name_format = argv[i]
            i += 1
            continue
        if arg.startswith("--log-name-format="):
            args.log_name_format = arg.split("=", 1)[1]
            i += 1
            continue
        if arg == "--password":
            i += 1
            if i >= len(argv):
                raise CapsLogError("the required argument for option '--password' is missing")
            args.password = argv[i]
            i += 1
            continue
        if arg.startswith("--password="):
            args.password = arg.split("=", 1)[1]
            i += 1
            continue
        if arg == "--sunday-start":
            args.sunday_start = True
            i += 1
            continue
        if arg == "--first-line-section":
            args.first_line_section = True
            i += 1
            continue
        if arg == "--encrypt":
            args.encrypt = True
            i += 1
            continue
        if arg == "--decrypt":
            args.decrypt = True
            i += 1
            continue
        if arg.startswith("-"):
            raise CapsLogError(f"unrecognised option '{arg}'")
        raise CapsLogError("too many positional options have been specified on the command line")
    return args


def parse_config(path: Path) -> Tuple[Dict[str, str], Dict[str, Dict[str, str]]]:
    try:
        raw_lines = path.read_text(encoding="utf-8").splitlines()
    except OSError:
        raise CapsLogError(f"Failed to open file: {path}")

    top_level: Dict[str, str] = {}
    sections: Dict[str, Dict[str, str]] = defaultdict(dict)
    current_section: Optional[str] = None

    for raw_line in raw_lines:
        line = raw_line.strip()
        if not line or line.startswith("#") or line.startswith(";"):
            continue
        if line.startswith("[") and line.endswith("]"):
            current_section = line[1:-1].strip()
            continue
        if "=" not in line:
            continue
        key, value = line.split("=", 1)
        key = key.strip()
        value = strip_inline_comment(value.strip())
        if current_section:
            sections[current_section][key] = value
        else:
            top_level[key] = value
    return top_level, sections


def parse_annual_events(sections: Dict[str, Dict[str, str]]) -> Tuple[int, List[AnnualEvent]]:
    recent_events_window = 60
    if "calendar-events" in sections and "recent-events-window" in sections["calendar-events"]:
        try:
            recent_events_window = int(sections["calendar-events"]["recent-events-window"])
        except ValueError:
            recent_events_window = 60

    events: List[AnnualEvent] = []
    for section_name, values in sections.items():
        if not section_name.startswith("calendar-events."):
            continue
        parts = section_name.split(".")
        if len(parts) < 3:
            continue
        group = parts[1]
        name = values.get("name", "").strip()
        date_value = values.get("date", "").strip()
        match = re.match(r"^\s*(\d{1,2})\.(\d{1,2})\.?\s*$", date_value)
        if not name or not match:
            continue
        day = int(match.group(1))
        month = int(match.group(2))
        if not 1 <= month <= 12:
            continue
        if not 1 <= day <= 31:
            continue
        display_group = group.replace("birthadays", "birthdays")
        events.append(AnnualEvent(group=display_group, name=name, month=month, day=day))
    events.sort(key=lambda item: (item.group.lower(), item.month, item.day, item.name.lower()))
    return recent_events_window, events


def merge_settings(cli: ParsedArgs) -> Settings:
    config_path = expand_path(cli.config_path) or default_config_path()
    top_level, sections = parse_config(config_path)

    log_dir = expand_path(cli.log_dir_path) or expand_path(top_level.get("log-dir-path")) or default_log_dir()
    log_name_format = cli.log_name_format or top_level.get("log-name-format") or top_level.get("log-filename-format") or DEFAULT_LOG_NAME_FORMAT
    sunday_start = cli.sunday_start or parse_bool(top_level.get("sunday-start", "false"))
    first_line_section = cli.first_line_section or parse_bool(top_level.get("first-line-section", "false"))
    password = cli.password if cli.password is not None else top_level.get("password")
    recent_events_window, annual_events = parse_annual_events(sections)
    return Settings(
        config_path=config_path,
        log_dir=log_dir,
        log_name_format=log_name_format,
        sunday_start=sunday_start,
        first_line_section=first_line_section,
        password=password,
        encrypt=cli.encrypt,
        decrypt=cli.decrypt,
        recent_events_window=recent_events_window,
        annual_events=annual_events,
    )


@dataclass
class DatePattern:
    regex: re.Pattern[str]
    groups: List[Tuple[str, str]]


def build_date_pattern(fmt: str) -> DatePattern:
    parts: List[str] = ["^"]
    groups: List[Tuple[str, str]] = []
    counters = Counter()
    i = 0
    while i < len(fmt):
        char = fmt[i]
        if char != "%":
            parts.append(re.escape(char))
            i += 1
            continue
        i += 1
        if i >= len(fmt):
            parts.append(re.escape("%"))
            break
        token = fmt[i]
        i += 1
        counters[token] += 1
        group_name = f"{token}{counters[token]}"
        if token == "Y":
            parts.append(f"(?P<{group_name}>\\d{{4}})")
            groups.append((group_name, "Y"))
        elif token == "y":
            parts.append(f"(?P<{group_name}>\\d{{2}})")
            groups.append((group_name, "y"))
        elif token == "m":
            parts.append(f"(?P<{group_name}>\\d{{2}})")
            groups.append((group_name, "m"))
        elif token == "d":
            parts.append(f"(?P<{group_name}>\\d{{2}})")
            groups.append((group_name, "d"))
        else:
            parts.append(re.escape("%" + token))
    parts.append("$")
    return DatePattern(regex=re.compile("".join(parts)), groups=groups)


def match_date(pattern: DatePattern, rel_path: str) -> Optional[dt.date]:
    match = pattern.regex.match(rel_path)
    if not match:
        return None

    year: Optional[int] = None
    month: Optional[int] = None
    day: Optional[int] = None
    for group_name, kind in pattern.groups:
        value = int(match.group(group_name))
        if kind == "Y":
            parsed = value
            if year is None:
                year = parsed
            elif year != parsed:
                return None
        elif kind == "y":
            parsed = 1900 + value if value >= 69 else 2000 + value
            if year is None:
                year = parsed
            elif year != parsed:
                return None
        elif kind == "m":
            if month is None:
                month = value
            elif month != value:
                return None
        elif kind == "d":
            if day is None:
                day = value
            elif day != value:
                return None

    if year is None or month is None or day is None:
        return None

    try:
        return dt.date(year, month, day)
    except ValueError:
        return None


def parse_log_content(content: str, first_line_section: bool) -> Tuple[List[str], List[Tuple[str, str]]]:
    section_names: List[str] = []
    tags: List[Tuple[str, str]] = []
    current_section = ROOT_SECTION
    root_needed = False
    lines = content.splitlines()
    for idx, line in enumerate(lines):
        if line.startswith("# "):
            if idx == 0 and not first_line_section:
                continue
            current_section = normalize_name(line[2:])
            if current_section:
                if current_section not in section_names:
                    section_names.append(current_section)
            continue
        if line.startswith("* "):
            tag = normalize_tag(line[2:])
            if tag:
                tags.append((current_section, tag))
                if current_section == ROOT_SECTION:
                    root_needed = True
            continue
        if current_section == ROOT_SECTION and line.strip():
            root_needed = True

    if root_needed and ROOT_SECTION not in section_names:
        section_names.insert(0, ROOT_SECTION)
    return section_names, tags


def marker_bytes(password: str) -> bytes:
    return hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), b"caps-log-marker", 2048, 18)


def marker_path(log_dir: Path) -> Path:
    return log_dir / ".cle"


def read_marker(log_dir: Path) -> Optional[bytes]:
    path = marker_path(log_dir)
    try:
        return path.read_bytes()
    except FileNotFoundError:
        return None


def validate_password(log_dir: Path, password: str) -> bool:
    stored = read_marker(log_dir)
    if stored is None:
        return False
    return stored == marker_bytes(password)


def apply_encrypt(settings: Settings) -> int:
    if not settings.password:
        raise CapsLogError("Password must be provided when encrypting logs!")
    print("Applying crypto...")
    if marker_path(settings.log_dir).exists():
        raise CapsLogError("Already applied")
    if not settings.log_dir.exists():
        raise CapsLogError(
            f"filesystem error: directory iterator cannot open directory: No such file or directory [{settings.log_dir}]"
        )
    marker_path(settings.log_dir).write_bytes(marker_bytes(settings.password))
    return 0


def apply_decrypt(settings: Settings) -> int:
    if not settings.password:
        raise CapsLogError("Password must be provided when decrypting logs!")
    print("Applying crypto...")
    path = marker_path(settings.log_dir)
    if not path.exists():
        raise CapsLogError("Already applied")
    path.unlink()
    return 0


def list_scratchpads(log_dir: Path) -> List[str]:
    scratch_dir = log_dir / "scratchpads"
    if not scratch_dir.exists():
        return []
    names: List[str] = []
    for path in scratch_dir.glob("*.md"):
        if path.is_file():
            names.append(path.stem)
    return sorted(names, key=lambda item: item.lower())


def load_entries(log_dir: Path, log_name_format: str, first_line_section: bool) -> Dict[dt.date, LogEntry]:
    pattern = build_date_pattern(log_name_format)
    entries: Dict[dt.date, LogEntry] = {}
    if not log_dir.exists():
        return entries
    for path in sorted(log_dir.rglob("*")):
        if not path.is_file():
            continue
        if path.name == ".cle":
            continue
        try:
            rel = path.relative_to(log_dir).as_posix()
        except ValueError:
            continue
        if rel.startswith("scratchpads/"):
            continue
        parsed_date = match_date(pattern, rel)
        if parsed_date is None:
            continue
        try:
            content = path.read_text(encoding="utf-8")
        except UnicodeDecodeError:
            content = path.read_text(encoding="utf-8", errors="replace")
        section_names, tags = parse_log_content(content, first_line_section)
        entries[parsed_date] = LogEntry(
            date=parsed_date,
            path=path,
            content=content,
            section_names=section_names,
            tags=tags,
        )
    return entries


def format_log_path(log_dir: Path, log_name_format: str, date_value: dt.date) -> Path:
    return log_dir / date_value.strftime(log_name_format)


def format_scratchpad_path(log_dir: Path, name: str) -> Path:
    return log_dir / "scratchpads" / f"{name}.md"


def safe_replace_year(date_value: dt.date, year: int) -> dt.date:
    try:
        return date_value.replace(year=year)
    except ValueError:
        return date_value.replace(year=year, month=2, day=28)


def event_display(event: AnnualEvent, today: dt.date) -> str:
    current_year_date = dt.date(today.year, event.month, event.day)
    if current_year_date >= today:
        delta = (current_year_date - today).days
        if delta == 0:
            detail = "(today)"
        elif delta == 1:
            detail = "(in 1 day)"
        else:
            detail = f"(in {delta} days)"
    else:
        delta = (today - current_year_date).days
        if delta == 1:
            detail = "(1 day ago)"
        else:
            detail = f"({delta} days ago)"
    return f"- {event.name} {event.day:02d}.{event.month:02d}. {detail}"


class CapsLogUI:
    def __init__(self, stdscr: "curses._CursesWindow", settings: Settings, repo_encrypted: bool, start_authenticated: bool):
        self.stdscr = stdscr
        self.settings = settings
        self.repo_encrypted = repo_encrypted
        self.authenticated = start_authenticated
        self.today = dt.date.today()
        self.display_year = self.today.year
        self.selected_date = self.today
        self.focus = "sections"
        self.entries: Dict[dt.date, LogEntry] = {}
        self.scratchpads: List[str] = []
        self.section_index = 0
        self.tag_index = 0
        self.selected_section: Optional[str] = None
        self.selected_tag: Optional[str] = None
        self.in_scratchpad = False
        self.scratch_index = 0
        self.modal: Optional[PromptModal] = None
        self.running = True
        self.error_after_exit: Optional[str] = None

        locale.setlocale(locale.LC_ALL, "")
        curses.curs_set(0)
        self.stdscr.keypad(True)
        curses.noecho()
        curses.cbreak()
        self._init_colors()

        self.reload_data()
        if self.repo_encrypted and not self.authenticated:
            self.modal = PromptModal(kind="password", title="Enter password for log files:", hidden=True)

    def _init_colors(self) -> None:
        if not curses.has_colors():
            return
        curses.start_color()
        curses.use_default_colors()
        curses.init_pair(1, curses.COLOR_RED, -1)
        curses.init_pair(2, curses.COLOR_BLUE, -1)
        curses.init_pair(3, curses.COLOR_GREEN, -1)
        curses.init_pair(4, curses.COLOR_YELLOW, -1)
        curses.init_pair(5, curses.COLOR_CYAN, -1)
        curses.init_pair(6, curses.COLOR_WHITE, -1)
        curses.init_pair(7, curses.COLOR_BLACK, curses.COLOR_WHITE)

    def color(self, pair: int, *attrs: int) -> int:
        value = curses.color_pair(pair)
        for attr in attrs:
            value |= attr
        return value

    def reload_data(self) -> None:
        if self.authenticated:
            self.entries = load_entries(self.settings.log_dir, self.settings.log_name_format, self.settings.first_line_section)
        else:
            self.entries = {}
        self.scratchpads = list_scratchpads(self.settings.log_dir)
        self._clamp_state()

    def _clamp_state(self) -> None:
        self.selected_date = safe_replace_year(self.selected_date, self.display_year)
        sections = self.section_items()
        if sections:
            self.section_index = max(0, min(self.section_index, len(sections) - 1))
            self.selected_section = sections[self.section_index][0]
        else:
            self.section_index = 0
            self.selected_section = None
        tags = self.tag_items()
        if tags:
            self.tag_index = max(0, min(self.tag_index, len(tags) - 1))
            self.selected_tag = tags[self.tag_index][0]
        else:
            self.tag_index = 0
            self.selected_tag = None
        scratch_count = len(self.scratchpads) + 1
        self.scratch_index = max(0, min(self.scratch_index, max(0, scratch_count - 1)))

    def run(self) -> int:
        while self.running:
            self.draw()
            key = self.stdscr.get_wch()
            self.handle_key(key)
        if self.error_after_exit:
            raise CapsLogError(self.error_after_exit)
        return 0

    def yearly_entries(self) -> Dict[dt.date, LogEntry]:
        return {date_value: entry for date_value, entry in self.entries.items() if date_value.year == self.display_year}

    def year_count(self) -> int:
        return len(self.yearly_entries())

    def section_counter(self) -> Counter[str]:
        counter: Counter[str] = Counter()
        for entry in self.yearly_entries().values():
            for section in dict.fromkeys(entry.section_names):
                counter[section] += 1
        return counter

    def tag_counter(self, section_filter: Optional[str]) -> Counter[str]:
        counter: Counter[str] = Counter()
        for entry in self.yearly_entries().values():
            seen: set[str] = set()
            for section_name, tag_name in entry.tags:
                if section_filter and section_name != section_filter:
                    continue
                if tag_name in seen:
                    continue
                seen.add(tag_name)
                counter[tag_name] += 1
        return counter

    def section_items(self) -> List[Tuple[Optional[str], Optional[int], str]]:
        if not self.authenticated:
            return []
        counter = self.section_counter()
        items: List[Tuple[Optional[str], Optional[int], str]] = [(None, None, "<select none>")]
        keys = list(counter.keys())
        keys.sort(key=lambda item: (item != ROOT_SECTION, -counter[item], item))
        for key in keys:
            items.append((key, counter[key], key))
        return items

    def tag_items(self) -> List[Tuple[Optional[str], Optional[int], str]]:
        if not self.authenticated:
            return []
        counter = self.tag_counter(self.selected_section)
        items: List[Tuple[Optional[str], Optional[int], str]] = [(None, None, "<select none>")]
        keys = sorted(counter.keys(), key=lambda item: (-counter[item], item))
        for key in keys:
            items.append((key, counter[key], key))
        return items

    def entry_matches_filter(self, entry: LogEntry) -> bool:
        if self.selected_section and self.selected_section not in entry.section_names:
            return False
        if self.selected_tag:
            if self.selected_section:
                return any(section == self.selected_section and tag == self.selected_tag for section, tag in entry.tags)
            return any(tag == self.selected_tag for _, tag in entry.tags)
        return True

    def event_dates(self) -> set[dt.date]:
        dates: set[dt.date] = set()
        for event in self.settings.annual_events:
            try:
                dates.add(dt.date(self.display_year, event.month, event.day))
            except ValueError:
                continue
        return dates

    def preview_title(self) -> str:
        if self.repo_encrypted and not self.authenticated:
            return "log preview"
        return f"log preview for {self.selected_date.strftime('%d. %m. %y. ')}"

    def preview_lines(self) -> List[Tuple[str, int]]:
        if self.repo_encrypted and not self.authenticated:
            return [("", 0)]
        entry = self.entries.get(self.selected_date)
        if entry is None:
            return [("", 0)]
        lines: List[Tuple[str, int]] = []
        for raw_line in entry.content.splitlines() or [""]:
            attr = 0
            if raw_line.startswith("# "):
                attr = self.color(4, curses.A_BOLD)
            elif raw_line.startswith("* "):
                attr = self.color(2)
            elif raw_line.startswith("> "):
                attr = self.color(5)
            lines.append((raw_line, attr))
        return lines

    def event_lines(self) -> List[str]:
        if not self.settings.annual_events:
            return []
        today = self.today
        lines: List[str] = []
        grouped: Dict[str, List[AnnualEvent]] = defaultdict(list)
        for event in self.settings.annual_events:
            grouped[event.group].append(event)
        for group in sorted(grouped.keys()):
            lines.append(group)
            for event in grouped[group]:
                lines.append(" " + event_display(event, today))
        return lines

    def open_editor(self, path: Path) -> None:
        editor = os.environ.get("EDITOR", "vi").strip() or "vi"
        command = shlex.split(editor) + [str(path)]
        curses.def_prog_mode()
        curses.endwin()
        try:
            subprocess.run(command, check=False)
        finally:
            curses.reset_prog_mode()
            curses.curs_set(0)
            self.stdscr.keypad(True)
            self.stdscr.refresh()
        self.reload_data()

    def delete_selected_log(self) -> None:
        path = format_log_path(self.settings.log_dir, self.settings.log_name_format, self.selected_date)
        try:
            path.unlink()
        except FileNotFoundError:
            return
        self.reload_data()

    def handle_key(self, key: object) -> None:
        if key in ("\x03",):
            self.running = False
            return
        if self.modal is not None:
            self.handle_modal_key(key)
            return
        if self.in_scratchpad:
            self.handle_scratchpad_key(key)
        else:
            self.handle_main_key(key)

    def handle_modal_key(self, key: object) -> None:
        assert self.modal is not None
        if isinstance(key, str):
            if key == "\x1b":
                if self.modal.kind == "delete":
                    self.modal.choice = 1
                else:
                    self.running = False
                return
            if key in ("\n", "\r"):
                self.submit_modal()
                return
            if key in ("\t",):
                if self.modal.kind == "delete":
                    self.modal.choice = 1 - self.modal.choice
                return
            if key in ("\b", "\x7f"):
                self.modal.buffer = self.modal.buffer[:-1]
                return
            if key in ("h", "l") and self.modal.kind == "delete":
                self.modal.choice = 0 if key == "h" else 1
                return
            if key.isprintable():
                self.modal.buffer += key
                return
        elif key == curses.KEY_BACKSPACE:
            self.modal.buffer = self.modal.buffer[:-1]
            return
        elif key in (curses.KEY_LEFT, curses.KEY_RIGHT) and self.modal.kind == "delete":
            self.modal.choice = 0 if key == curses.KEY_LEFT else 1

    def submit_modal(self) -> None:
        assert self.modal is not None
        if self.modal.kind == "password":
            if not validate_password(self.settings.log_dir, self.modal.buffer):
                self.running = False
                self.error_after_exit = "Invalid password provided!"
                return
            self.settings.password = self.modal.buffer
            self.authenticated = True
            self.modal = None
            self.reload_data()
            return
        if self.modal.kind == "delete":
            if self.modal.choice == 0:
                self.delete_selected_log()
            self.modal = None
            return
        if self.modal.kind == "scratchpad-name":
            name = self.modal.buffer.strip()
            self.modal = None
            if name:
                self.open_editor(format_scratchpad_path(self.settings.log_dir, name))

    def handle_main_key(self, key: object) -> None:
        if key == "q":
            self.running = False
            return
        if key == "s":
            self.in_scratchpad = True
            self.scratch_index = 0
            return
        if key == "r":
            self.reload_data()
            return
        if key == "\t":
            order = ["sections", "tags", "calendar"]
            self.focus = order[(order.index(self.focus) + 1) % len(order)]
            return
        if key == "+":
            self.display_year += 1
            self.selected_date = safe_replace_year(self.selected_date, self.display_year)
            self.reload_data()
            return
        if key == "-":
            self.display_year -= 1
            self.selected_date = safe_replace_year(self.selected_date, self.display_year)
            self.reload_data()
            return

        if self.focus == "sections":
            self.handle_sections_key(key)
        elif self.focus == "tags":
            self.handle_tags_key(key)
        else:
            self.handle_calendar_key(key)

    def handle_sections_key(self, key: object) -> None:
        items = self.section_items()
        if not items:
            return
        if key in ("j",) or key == curses.KEY_DOWN:
            self.section_index = min(self.section_index + 1, len(items) - 1)
        elif key in ("k",) or key == curses.KEY_UP:
            self.section_index = max(self.section_index - 1, 0)
        else:
            return
        self.selected_section = items[self.section_index][0]
        self.tag_index = 0
        self.selected_tag = None
        self._clamp_state()

    def handle_tags_key(self, key: object) -> None:
        items = self.tag_items()
        if not items:
            return
        if key in ("j",) or key == curses.KEY_DOWN:
            self.tag_index = min(self.tag_index + 1, len(items) - 1)
        elif key in ("k",) or key == curses.KEY_UP:
            self.tag_index = max(self.tag_index - 1, 0)
        else:
            return
        self.selected_tag = items[self.tag_index][0]

    def handle_calendar_key(self, key: object) -> None:
        if key in ("\n", "\r"):
            self.open_editor(format_log_path(self.settings.log_dir, self.settings.log_name_format, self.selected_date))
            return
        if key == "d":
            if self.selected_date in self.entries:
                self.modal = PromptModal(kind="delete", title="Are you sure you want to delete a log file?", choice=0)
            return
        deltas = {
            "h": -1,
            "l": 1,
            "j": 7,
            "k": -7,
            curses.KEY_LEFT: -1,
            curses.KEY_RIGHT: 1,
            curses.KEY_DOWN: 7,
            curses.KEY_UP: -7,
        }
        delta = deltas.get(key)
        if delta is None:
            return
        new_date = self.selected_date + dt.timedelta(days=delta)
        if new_date.year != self.display_year:
            return
        self.selected_date = new_date

    def handle_scratchpad_key(self, key: object) -> None:
        if key == "q":
            self.running = False
            return
        if key == "s":
            self.in_scratchpad = False
            return
        total_items = len(self.scratchpads) + 1
        if key in ("j",) or key == curses.KEY_DOWN:
            self.scratch_index = min(self.scratch_index + 1, total_items - 1)
            return
        if key in ("k",) or key == curses.KEY_UP:
            self.scratch_index = max(self.scratch_index - 1, 0)
            return
        if key in ("\n", "\r"):
            if self.scratch_index == 0:
                self.modal = PromptModal(kind="scratchpad-name", title="Enter the name of the scratchpad to open:")
            else:
                name = self.scratchpads[self.scratch_index - 1]
                self.open_editor(format_scratchpad_path(self.settings.log_dir, name))

    def draw(self) -> None:
        self.stdscr.erase()
        height, width = self.stdscr.getmaxyx()
        if self.in_scratchpad:
            self.draw_scratchpad_view(height, width)
        else:
            self.draw_main_view(height, width)
        if self.modal:
            self.draw_modal(height, width)
        self.stdscr.refresh()

    def draw_main_view(self, height: int, width: int) -> None:
        header = f"Today is: {self.today.strftime('%d. %m. %Y.')}  | There are {self.year_count()} log entries for year {self.display_year}."
        self.safe_addstr(0, max(0, (width - len(header)) // 2), header[: width - 1], curses.A_BOLD)

        preview_height = max(5, min(8, height // 4))
        top_height = max(12, height - preview_height - 2)
        left_width = min(40, max(28, width // 3))
        right_x = left_width + 1
        right_width = max(20, width - right_x)

        event_lines = self.event_lines()
        if event_lines:
            top_box_height = max(8, top_height - 7)
            event_height = top_height - top_box_height
        else:
            top_box_height = top_height
            event_height = 0

        menu_width = max(14, left_width // 2)
        tags_width = max(14, left_width - menu_width)
        self.draw_box(1, 0, top_box_height, menu_width, "Sections", dim=self.focus != "sections")
        self.draw_box(1, menu_width, top_box_height, tags_width, "Tags", dim=self.focus != "tags")
        self.draw_box(1, right_x, top_height, right_width, str(self.display_year), dim=self.focus != "calendar")

        sections = self.section_items()
        tags = self.tag_items()
        self.draw_menu_items(2, 1, top_box_height - 2, menu_width - 2, sections, self.section_index, self.focus == "sections")
        self.draw_menu_items(2, menu_width + 1, top_box_height - 2, tags_width - 2, tags, self.tag_index, self.focus == "tags")

        if event_height > 0:
            self.draw_box(1 + top_box_height, 0, event_height, left_width, "", dim=True)
            self.draw_lines(2 + top_box_height, 1, event_height - 2, left_width - 2, [(line, 0) for line in event_lines])

        self.draw_calendar(2, right_x + 1, top_height - 2, right_width - 2)

        preview_y = 1 + top_height
        self.draw_box(preview_y, 0, height - preview_y, width, self.preview_title(), dim=False)
        self.draw_lines(preview_y + 1, 1, max(0, height - preview_y - 2), max(0, width - 2), self.preview_lines())

    def draw_scratchpad_view(self, height: int, width: int) -> None:
        title = "Scratchpad Manager"
        self.safe_addstr(0, max(0, (width - len(title)) // 2), title[: width - 1], curses.A_BOLD)
        self.safe_addstr(1, 0, "\u2500" * max(0, width - 1))
        left_width = min(32, max(24, width // 3))
        right_x = left_width + 1
        right_width = width - right_x
        body_height = max(5, height - 2)

        self.draw_box(2, 0, body_height, left_width, "Scratchpads", dim=False)
        self.draw_box(2, right_x, body_height, right_width, "Select a scratchpad", dim=True)

        items = [("Make new scratchpad", 0)] + [(name, 0) for name in self.scratchpads]
        lines = [(label, 0) for label, _ in items]
        self.draw_simple_list(3, 1, body_height - 2, left_width - 2, lines, self.scratch_index)

        preview: List[Tuple[str, int]]
        if self.scratch_index == 0:
            preview = [("No scratchpad selected", 0)]
        else:
            path = format_scratchpad_path(self.settings.log_dir, self.scratchpads[self.scratch_index - 1])
            if path.exists():
                try:
                    content = path.read_text(encoding="utf-8").splitlines()
                except UnicodeDecodeError:
                    content = path.read_text(encoding="utf-8", errors="replace").splitlines()
                preview = [(line, 0) for line in content] or [("", 0)]
            else:
                preview = [("No scratchpad selected", 0)]
        self.draw_lines(3, right_x + 1, body_height - 2, right_width - 2, preview)

    def draw_calendar(self, y: int, x: int, h: int, w: int) -> None:
        firstweekday = 6 if self.settings.sunday_start else 0
        cal = calendar.Calendar(firstweekday=firstweekday)
        month_width = max(16, (w - 3) // 4)
        month_height = 7
        event_dates = self.event_dates()
        for month in range(1, 13):
            row = (month - 1) // 4
            col = (month - 1) % 4
            box_y = y + row * month_height
            box_x = x + col * month_width
            if box_y + 6 >= y + h:
                break
            title = dt.date(self.display_year, month, 1).strftime("%B")
            self.safe_addstr(box_y, box_x, title[: max(1, month_width - 1)], curses.A_BOLD)
            header = " ".join(calendar.day_abbr[(firstweekday + offset) % 7][0] for offset in range(7))
            self.safe_addstr(box_y + 1, box_x, header[: max(1, month_width - 1)], curses.A_UNDERLINE)
            weeks = cal.monthdayscalendar(self.display_year, month)
            for week_idx, week in enumerate(weeks[:5]):
                line_y = box_y + 2 + week_idx
                current_x = box_x
                for day in week:
                    if current_x + 2 >= x + w:
                        break
                    if day == 0:
                        self.safe_addstr(line_y, current_x, "  ")
                    else:
                        date_value = dt.date(self.display_year, month, day)
                        attr = 0
                        if date_value in event_dates:
                            attr |= self.color(3)
                        weekday = date_value.weekday()
                        if (not self.settings.sunday_start and weekday >= 5) or (self.settings.sunday_start and date_value.isoweekday() in {6, 7}):
                            attr |= self.color(2)
                        if date_value in self.entries:
                            attr |= curses.A_UNDERLINE
                            if self.selected_section or self.selected_tag:
                                entry = self.entries[date_value]
                                if self.entry_matches_filter(entry):
                                    attr |= self.color(4, curses.A_BOLD)
                        if date_value == self.today:
                            attr |= self.color(1)
                        if date_value == self.selected_date:
                            attr |= curses.A_REVERSE
                        self.safe_addstr(line_y, current_x, f"{day:2d}", attr)
                    current_x += 3

    def draw_modal(self, height: int, width: int) -> None:
        if self.modal is None:
            return
        if self.modal.kind == "delete":
            box_width = min(43, max(30, width - 8))
            box_height = 6
        else:
            box_width = min(41, max(30, width - 8))
            box_height = 6
        start_y = max(2, (height - box_height) // 2)
        start_x = max(0, (width - box_width) // 2)
        self.draw_box(start_y, start_x, box_height, box_width, "", dim=False)
        self.safe_addstr(start_y + 1, start_x + 1, self.modal.title[: box_width - 2])
        if self.modal.kind == "delete":
            yes_attr = curses.A_REVERSE if self.modal.choice == 0 else 0
            no_attr = curses.A_REVERSE if self.modal.choice == 1 else 0
            self.safe_addstr(start_y + 3, start_x + box_width // 2 - 6, "Yes", yes_attr)
            self.safe_addstr(start_y + 3, start_x + box_width // 2 + 2, "No", no_attr)
        else:
            shown = " " * min(len(self.modal.buffer), box_width - 4) if self.modal.hidden else self.modal.buffer[-(box_width - 4) :]
            self.safe_addstr(start_y + 3, start_x + 1, shown.ljust(box_width - 2), curses.A_REVERSE)
            self.safe_addstr(start_y + 4, start_x + box_width // 2 - 3, "Submit")

    def draw_menu_items(
        self,
        y: int,
        x: int,
        h: int,
        w: int,
        items: List[Tuple[Optional[str], Optional[int], str]],
        selected_index: int,
        focused: bool,
    ) -> None:
        if not items:
            return
        visible = items[:h]
        for idx, (_, count, label) in enumerate(visible):
            prefix = ">" if idx == selected_index else " "
            if count is None:
                text = f"{prefix} {label}"
            else:
                text = f" {count:4d} | {label}"
            attr = curses.A_REVERSE if focused and idx == selected_index else 0
            self.safe_addstr(y + idx, x, text[:w].ljust(w), attr)

    def draw_simple_list(self, y: int, x: int, h: int, w: int, items: List[Tuple[str, int]], selected_index: int) -> None:
        for idx, (label, attr) in enumerate(items[:h]):
            prefix = ">" if idx == selected_index else " "
            line_attr = curses.A_REVERSE if idx == selected_index else attr
            self.safe_addstr(y + idx, x, f"{prefix} {label}"[:w].ljust(w), line_attr)

    def draw_lines(self, y: int, x: int, h: int, w: int, lines: List[Tuple[str, int]]) -> None:
        for idx in range(h):
            if idx >= len(lines):
                self.safe_addstr(y + idx, x, " " * max(0, w))
                continue
            text, attr = lines[idx]
            clipped = text[:w]
            self.safe_addstr(y + idx, x, clipped.ljust(w), attr)

    def draw_box(self, y: int, x: int, h: int, w: int, title: str, dim: bool = False) -> None:
        if h < 2 or w < 2:
            return
        attr = curses.A_DIM if dim else 0
        horiz = "\u2500" * max(0, w - 2)
        self.safe_addstr(y, x, "\u256d" + horiz + "\u256e", attr)
        for row in range(1, h - 1):
            self.safe_addstr(y + row, x, "\u2502", attr)
            self.safe_addstr(y + row, x + w - 1, "\u2502", attr)
            if w > 2:
                self.safe_addstr(y + row, x + 1, " " * (w - 2), attr)
        self.safe_addstr(y + h - 1, x, "\u2570" + horiz + "\u256f", attr)
        if title:
            shown = title[: max(0, w - 2)]
            self.safe_addstr(y, x + 1, shown, curses.A_DIM if dim else curses.A_NORMAL)

    def safe_addstr(self, y: int, x: int, text: str, attr: int = 0) -> None:
        if y < 0 or x < 0:
            return
        max_y, max_x = self.stdscr.getmaxyx()
        if y >= max_y or x >= max_x:
            return
        if not text:
            return
        clipped = text[: max(0, max_x - x)]
        try:
            self.stdscr.addstr(y, x, clipped, attr)
        except curses.error:
            pass


def run_tui(settings: Settings, repo_encrypted: bool, authenticated: bool) -> int:
    settings.log_dir.mkdir(parents=True, exist_ok=True)

    def wrapped(stdscr: "curses._CursesWindow") -> int:
        app = CapsLogUI(stdscr, settings, repo_encrypted=repo_encrypted, start_authenticated=authenticated)
        return app.run()

    return curses.wrapper(wrapped)


def main(argv: Sequence[str]) -> int:
    try:
        parsed = parse_args(argv)
        if parsed.help:
            sys.stdout.write(
                HELP_TEMPLATE.format(version=VERSION, config_path=str(default_config_path())) + ("\n" if not HELP_TEMPLATE.endswith("\n") else "")
            )
            return 0

        settings = merge_settings(parsed)

        if settings.encrypt:
            return apply_encrypt(settings)
        if settings.decrypt:
            return apply_decrypt(settings)

        encrypted = marker_path(settings.log_dir).exists()
        if settings.password and not encrypted:
            raise CapsLogError("Password provided for a non encrypted repository!")
        if encrypted and settings.password and not validate_password(settings.log_dir, settings.password):
            raise CapsLogError("Invalid password provided!")

        authenticated = not encrypted or bool(settings.password)
        return run_tui(settings, repo_encrypted=encrypted, authenticated=authenticated)
    except KeyboardInterrupt:
        return 0
    except CapsLogError as exc:
        sys.stderr.write(format_error(str(exc)))
        return 1


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))

