@dataclass
class DatePattern:
    regex: re.Pattern[str]
    groups: List[Tuple[str, str]]


def build_date_pattern(fmt: str) -> DatePattern:
    parts: List[str] = ["^"]
    groups: List[Tuple[str, str]] = []
    counters = Counter()
    i = 0
    while i < len(fmt):
        char = fmt[i]
        if char != "%":
            parts.append(re.escape(char))
            i += 1
            continue
        i += 1
        if i >= len(fmt):
            parts.append(re.escape("%"))
            break
        token = fmt[i]
        i += 1
        counters[token] += 1
        group_name = f"{token}{counters[token]}"
        if token == "Y":
            parts.append(f"(?P<{group_name}>\\d{{4}})")
            groups.append((group_name, "Y"))
        elif token == "y":
            parts.append(f"(?P<{group_name}>\\d{{2}})")
            groups.append((group_name, "y"))
        elif token == "m":
            parts.append(f"(?P<{group_name}>\\d{{2}})")
            groups.append((group_name, "m"))
        elif token == "d":
            parts.append(f"(?P<{group_name}>\\d{{2}})")
            groups.append((group_name, "d"))
        else:
            parts.append(re.escape("%" + token))
    parts.append("$")
    return DatePattern(regex=re.compile("".join(parts)), groups=groups)


def match_date(pattern: DatePattern, rel_path: str) -> Optional[dt.date]:
    match = pattern.regex.match(rel_path)
    if not match:
        return None

    year: Optional[int] = None
    month: Optional[int] = None
    day: Optional[int] = None
    for group_name, kind in pattern.groups:
        value = int(match.group(group_name))
        if kind == "Y":
            parsed = value
            if year is None:
                year = parsed
            elif year != parsed:
                return None
        elif kind == "y":
            parsed = 1900 + value if value >= 69 else 2000 + value
            if year is None:
                year = parsed
            elif year != parsed:
                return None
        elif kind == "m":
            if month is None:
                month = value
            elif month != value:
                return None
        elif kind == "d":
            if day is None:
                day = value
            elif day != value:
                return None

    if year is None or month is None or day is None:
        return None

    try:
        return dt.date(year, month, day)
    except ValueError:
        return None


def parse_log_content(content: str, first_line_section: bool) -> Tuple[List[str], List[Tuple[str, str]]]:
    section_names: List[str] = []
    tags: List[Tuple[str, str]] = []
    current_section = ROOT_SECTION
    root_needed = False
    lines = content.splitlines()
    for idx, line in enumerate(lines):
        if line.startswith("# "):
            if idx == 0 and not first_line_section:
                continue
            current_section = normalize_name(line[2:])
            if current_section:
                if current_section not in section_names:
                    section_names.append(current_section)
            continue
        if line.startswith("* "):
            tag = normalize_tag(line[2:])
            if tag:
                tags.append((current_section, tag))
                if current_section == ROOT_SECTION:
                    root_needed = True
            continue
        if current_section == ROOT_SECTION and line.strip():
            root_needed = True

    if root_needed and ROOT_SECTION not in section_names:
        section_names.insert(0, ROOT_SECTION)
    return section_names, tags


def marker_bytes(password: str) -> bytes:
    return hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), b"caps-log-marker", 2048, 18)


def marker_path(log_dir: Path) -> Path:
    return log_dir / ".cle"


def read_marker(log_dir: Path) -> Optional[bytes]:
    path = marker_path(log_dir)
    try:
        return path.read_bytes()
    except FileNotFoundError:
        return None


def validate_password(log_dir: Path, password: str) -> bool:
    stored = read_marker(log_dir)
    if stored is None:
        return False
    return stored == marker_bytes(password)


def apply_encrypt(settings: Settings) -> int:
    if not settings.password:
        raise CapsLogError("Password must be provided when encrypting logs!")
    print("Applying crypto...")
    if marker_path(settings.log_dir).exists():
        raise CapsLogError("Already applied")
    if not settings.log_dir.exists():
        raise CapsLogError(
            f"filesystem error: directory iterator cannot open directory: No such file or directory [{settings.log_dir}]"
        )
    marker_path(settings.log_dir).write_bytes(marker_bytes(settings.password))
    return 0


def apply_decrypt(settings: Settings) -> int:
    if not settings.password:
        raise CapsLogError("Password must be provided when decrypting logs!")
    print("Applying crypto...")
    path = marker_path(settings.log_dir)
    if not path.exists():
        raise CapsLogError("Already applied")
    path.unlink()
    return 0


def list_scratchpads(log_dir: Path) -> List[str]:
    scratch_dir = log_dir / "scratchpads"
    if not scratch_dir.exists():
        return []
    names: List[str] = []
    for path in scratch_dir.glob("*.md"):
        if path.is_file():
            names.append(path.stem)
    return sorted(names, key=lambda item: item.lower())


def load_entries(log_dir: Path, log_name_format: str, first_line_section: bool) -> Dict[dt.date, LogEntry]:
    pattern = build_date_pattern(log_name_format)
    entries: Dict[dt.date, LogEntry] = {}
    if not log_dir.exists():
        return entries
    for path in sorted(log_dir.rglob("*")):
        if not path.is_file():
            continue
        if path.name == ".cle":
            continue
        try:
            rel = path.relative_to(log_dir).as_posix()
        except ValueError:
            continue
        if rel.startswith("scratchpads/"):
            continue
        parsed_date = match_date(pattern, rel)
        if parsed_date is None:
            continue
        try:
            content = path.read_text(encoding="utf-8")
        except UnicodeDecodeError:
            content = path.read_text(encoding="utf-8", errors="replace")
        section_names, tags = parse_log_content(content, first_line_section)
        entries[parsed_date] = LogEntry(
            date=parsed_date,
            path=path,
            content=content,
            section_names=section_names,
            tags=tags,
        )
    return entries

