    def handle_modal_key(self, key: object) -> None:
        assert self.modal is not None
        if isinstance(key, str):
            if key == "\x1b":
                if self.modal.kind == "delete":
                    self.modal.choice = 1
                else:
                    self.running = False
                return
            if key in ("\n", "\r"):
                self.submit_modal()
                return
            if key in ("\t",):
                if self.modal.kind == "delete":
                    self.modal.choice = 1 - self.modal.choice
                return
            if key in ("\b", "\x7f"):
                self.modal.buffer = self.modal.buffer[:-1]
                return
            if key in ("h", "l") and self.modal.kind == "delete":
                self.modal.choice = 0 if key == "h" else 1
                return
            if key.isprintable():
                self.modal.buffer += key
                return
        elif key == curses.KEY_BACKSPACE:
            self.modal.buffer = self.modal.buffer[:-1]
            return
        elif key in (curses.KEY_LEFT, curses.KEY_RIGHT) and self.modal.kind == "delete":
            self.modal.choice = 0 if key == curses.KEY_LEFT else 1

    def submit_modal(self) -> None:
        assert self.modal is not None
        if self.modal.kind == "password":
            if not validate_password(self.settings.log_dir, self.modal.buffer):
                self.running = False
                self.error_after_exit = "Invalid password provided!"
                return
            self.settings.password = self.modal.buffer
            self.authenticated = True
            self.modal = None
            self.reload_data()
            return
        if self.modal.kind == "delete":
            if self.modal.choice == 0:
                self.delete_selected_log()
            self.modal = None
            return
        if self.modal.kind == "scratchpad-name":
            name = self.modal.buffer.strip()
            self.modal = None
            if name:
                self.open_editor(format_scratchpad_path(self.settings.log_dir, name))

    def handle_main_key(self, key: object) -> None:
        if key == "q":
            self.running = False
            return
        if key == "s":
            self.in_scratchpad = True
            self.scratch_index = 0
            return
        if key == "r":
            self.reload_data()
            return
        if key == "\t":
            order = ["sections", "tags", "calendar"]
            self.focus = order[(order.index(self.focus) + 1) % len(order)]
            return
        if key == "+":
            self.display_year += 1
            self.selected_date = safe_replace_year(self.selected_date, self.display_year)
            self.reload_data()
            return
        if key == "-":
            self.display_year -= 1
            self.selected_date = safe_replace_year(self.selected_date, self.display_year)
            self.reload_data()
            return

        if self.focus == "sections":
            self.handle_sections_key(key)
        elif self.focus == "tags":
            self.handle_tags_key(key)
        else:
            self.handle_calendar_key(key)

    def handle_sections_key(self, key: object) -> None:
        items = self.section_items()
        if not items:
            return
        if key in ("j",) or key == curses.KEY_DOWN:
            self.section_index = min(self.section_index + 1, len(items) - 1)
        elif key in ("k",) or key == curses.KEY_UP:
            self.section_index = max(self.section_index - 1, 0)
        else:
            return
        self.selected_section = items[self.section_index][0]
        self.tag_index = 0
        self.selected_tag = None
        self._clamp_state()

    def handle_tags_key(self, key: object) -> None:
        items = self.tag_items()
        if not items:
            return
        if key in ("j",) or key == curses.KEY_DOWN:
            self.tag_index = min(self.tag_index + 1, len(items) - 1)
        elif key in ("k",) or key == curses.KEY_UP:
            self.tag_index = max(self.tag_index - 1, 0)
        else:
            return
        self.selected_tag = items[self.tag_index][0]

    def handle_calendar_key(self, key: object) -> None:
        if key in ("\n", "\r"):
            self.open_editor(format_log_path(self.settings.log_dir, self.settings.log_name_format, self.selected_date))
            return
        if key == "d":
            if self.selected_date in self.entries:
                self.modal = PromptModal(kind="delete", title="Are you sure you want to delete a log file?", choice=0)
            return
        deltas = {
            "h": -1,
            "l": 1,
            "j": 7,
            "k": -7,
            curses.KEY_LEFT: -1,
            curses.KEY_RIGHT: 1,
            curses.KEY_DOWN: 7,
            curses.KEY_UP: -7,
        }
        delta = deltas.get(key)
        if delta is None:
            return
        new_date = self.selected_date + dt.timedelta(days=delta)
        if new_date.year != self.display_year:
            return
        self.selected_date = new_date

    def handle_scratchpad_key(self, key: object) -> None:
        if key == "q":
            self.running = False
            return
        if key == "s":
            self.in_scratchpad = False
            return
        total_items = len(self.scratchpads) + 1
        if key in ("j",) or key == curses.KEY_DOWN:
            self.scratch_index = min(self.scratch_index + 1, total_items - 1)
            return
        if key in ("k",) or key == curses.KEY_UP:
            self.scratch_index = max(self.scratch_index - 1, 0)
            return
        if key in ("\n", "\r"):
            if self.scratch_index == 0:
                self.modal = PromptModal(kind="scratchpad-name", title="Enter the name of the scratchpad to open:")
            else:
                name = self.scratchpads[self.scratch_index - 1]
                self.open_editor(format_scratchpad_path(self.settings.log_dir, name))

