func printUserError(message string) {
	fmt.Fprintln(os.Stderr, "Captain's log encountered an error: ")
	fmt.Fprintln(os.Stderr, " "+message)
}

func encryptRepo(logDir, password string) error {
	if _, exists, err := crypto.ReadMarker(logDir); err != nil {
		return err
	} else if exists {
		return fmt.Errorf("Already applied")
	}

	if _, err := os.ReadDir(logDir); err != nil {
		if os.IsNotExist(err) {
			return fmt.Errorf("filesystem error: directory iterator cannot open directory: No such file or directory [%s]", logDir)
		}
		return err
	}

	return crypto.WriteMarker(logDir, password)
}

func decryptRepo(logDir string) error {
	if _, exists, err := crypto.ReadMarker(logDir); err != nil {
		return err
	} else if !exists {
		return fmt.Errorf("Already applied")
	}

	return crypto.RemoveMarker(logDir)
}

