const (
	MarkerFilename = ".cle"
	markerPlaintext = "encryption-marker:"
)

func MarkerPath(logDir string) string {
	return filepath.Join(logDir, MarkerFilename)
}

func MarkerBytes(password string) ([]byte, error) {
	key, iv := evpBytesToKeyMD5([]byte(password), 16, aes.BlockSize)

	block, err := aes.NewCipher(key)
	if err != nil {
		return nil, err
	}

	dst := make([]byte, len(markerPlaintext))
	stream := cipher.NewCFBEncrypter(block, iv)
	stream.XORKeyStream(dst, []byte(markerPlaintext))
	return dst, nil
}

func ValidateMarker(marker []byte, password string) bool {
	key, iv := evpBytesToKeyMD5([]byte(password), 16, aes.BlockSize)

	block, err := aes.NewCipher(key)
	if err != nil {
		return false
	}

	dst := make([]byte, len(marker))
	stream := cipher.NewCFBDecrypter(block, iv)
	stream.XORKeyStream(dst, marker)
	return bytes.Equal(dst, []byte(markerPlaintext))
}

func ReadMarker(logDir string) ([]byte, bool, error) {
	path := MarkerPath(logDir)
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, false, nil
		}
		return nil, false, fmt.Errorf("Failed to open file: %s", path)
	}
	return data, true, nil
}

func WriteMarker(logDir, password string) error {
	data, err := MarkerBytes(password)
	if err != nil {
		return err
	}
	return os.WriteFile(MarkerPath(logDir), data, 0o644)
}

func RemoveMarker(logDir string) error {
	return os.Remove(MarkerPath(logDir))
}

func evpBytesToKeyMD5(password []byte, keyLen, ivLen int) ([]byte, []byte) {
	total := keyLen + ivLen
	out := make([]byte, 0, total)
	prev := []byte{}

	for len(out) < total {
		sum := md5.Sum(append(prev, password...))
		prev = sum[:]
		out = append(out, prev...)
	}

	return out[:keyLen], out[keyLen:total]
}

