func (c *Canvas) Render() string {
	var out strings.Builder
	out.WriteString("\x1b[H")

	current := Style{Fg: -1}
	for y := 0; y < c.Height; y++ {
		for x := 0; x < c.Width; x++ {
			cell := c.Cells[y][x]
			if cell.Style != current {
				out.WriteString(styleANSI(cell.Style))
				current = cell.Style
			}
			out.WriteRune(cell.Ch)
		}
		out.WriteString("\x1b[0m")
		current = Style{Fg: -1}
		if y != c.Height-1 {
			out.WriteString("\r\n")
		}
	}
	return out.String()
}

func styleANSI(style Style) string {
	codes := []string{"0"}
	if style.Bold {
		codes = append(codes, "1")
	}
	if style.Dim {
		codes = append(codes, "2")
	}
	if style.Underline {
		codes = append(codes, "4")
	}
	if style.Inverse {
		codes = append(codes, "7")
	}
	if style.Fg >= 0 {
		codes = append(codes, fmt.Sprintf("%d", style.Fg))
	}
	return "\x1b[" + strings.Join(codes, ";") + "m"
}

func fitString(text string, width int) string {
	if width <= 0 {
		return ""
	}
	runes := []rune(text)
	if len(runes) <= width {
		return text + strings.Repeat(" ", width-len(runes))
	}
	return string(runes[:width])
}

func runeLen(text string) int {
