				}
				cfg.Git.RepoRoot = path
			}
			if value := section["remote-name"]; value != "" {
				cfg.Git.RemoteName = value
			}
			if value := section["main-branch-name"]; value != "" {
				cfg.Git.MainBranch = value
			}
		}
	}

