		path, err := expandPath(opts.LogDirPath, home)
		if err != nil {
			return Config{}, err
		}
		cfg.LogDirPath = path
	}
	if opts.LogNameFormat != "" {
		cfg.LogNameFormat = opts.LogNameFormat
	}
	if opts.SundayStart {
		cfg.SundayStart = true
	}
	if opts.FirstLineSection {
		cfg.FirstLineSection = true
	}
	if opts.Password != "" {
		cfg.Password = opts.Password
	}

	if cfg.Git.Enabled && cfg.Git.RepoRoot != "" {
		rel, err := filepath.Rel(cfg.Git.RepoRoot, cfg.LogDirPath)
		if err != nil || strings.HasPrefix(rel, "..") {
			return Config{}, fmt.Errorf("log-dir-path must be inside git.repo-root")
		}
	}

	return cfg, nil
}

func stripInlineComment(value string) string {
	for _, marker := range []string{" #", " ;"} {
		if index := strings.Index(value, marker); index >= 0 {
			return strings.TrimSpace(value[:index])
		}
	}
	return strings.TrimSpace(value)
}

